function kekerapan(senarai) {
  const m = new Map();
  for (const x of senarai) m.set(x, (m.get(x) ?? 0) + 1);
  return m;
}
console.log(kekerapan(['a', 'b', 'a']).get('a')); // 2
```
Map keeps any key type and insertion order with O(1) updates — cleaner than object counters (no prototype keys, no string coercion).

```js
function unikIkut(senarai, kunci) {
  return [...new Map(senarai.map(o => [o[kunci], o])).values()];
}
console.log(unikIkut([{ id: 1 }, { id: 1 }, { id: 2 }], 'id'));
// [{ id: 1 }, { id: 2 }] (kekal terakhir)
```
Later entries win with this pattern; reverse first for first-wins. For primitives, plain `[...new Set(a)]` suffices.

```js
class Kaunter {
  #n = 0;
  naik() { return ++this.#n; }
  static cipta() { return new Kaunter(); }
}
```
`#` fields are truly private (SyntaxError from outside, even subclasses). Use them instead of `_convention` privacy; expose via getters or methods only.

```js
function tambah(a, b) {
  return a + b;
}
console.log(tambah(4, 7)); // 11
```

```html
<div id="kuiz"></div>
<script>
const soalan = [
  { q: '2 + 2?', pilih: ['3', '4', '5'], betul: 1 },
  { q: 'Ibu kota MY?', pilih: ['KL', 'JB', 'PG'], betul: 0 },
];
let semasa = 0, skor = 0;
const div = document.getElementById('kuiz');
function papar() {
  const s = soalan[semasa];
  div.innerHTML = `<p>${s.q}</p>`;
  s.pilih.forEach((p, i) => {
    const b = document.createElement('button');
    b.textContent = p;
    b.onclick = () => {
      if (i === s.betul) skor++;
      if (++semasa < soalan.length) papar();
      else div.textContent = `Skor: ${skor}/${soalan.length}`;
    };
    div.append(b);
  });
}
papar();
</script>
```
State (semasa/skor) dipisah dari DOM; butang dibina (bukan innerHTML dengan handler rentetan!); akhir papar skor. Jawapan betul di pelayan untuk kuiz sebenar (klien boleh dibaca!).

